{
  "version": "0.1",
  "base_model": "economic_planning",
  "data_changes": [
    {
      "op": "set",
      "table": "input_output",
      "column": "input_per_unit_output",
      "where": {
        "supplier": "steel",
        "user": "steel"
      },
      "value": 0.5
    }
  ],
  "note": "The input per unit of output for steel using steel is changed directly in the input_output table."
}

{
  "version": "0.1",
  "base_model": "economic_planning",
  "rules": [
    {
      "name": "minimum_capacity_built",
      "measure": "extra_capacity",
      "scope": {
        "year": 5
      },
      "sense": ">=",
      "value": 890
    }
  ],
  "note": "The minimum capacity built is quantified as the total extra capacity built in year 5, summed over all industries."
}

{
  "version": "0.1",
  "base_model": "economic_planning",
  "rules": [
    {
      "name": "capacity_cap",
      "measure": "extra_capacity",
      "scope": {
        "year": [1, 2, 3, 4, 5]
      },
      "sense": "<=",
      "value": 100
    }
  ],
  "note": "A cap on the capacity built is applied to the extra_capacity decision variable across all years in the planning horizon."
}

{
  "version": "0.1",
  "base_model": "economic_planning",
  "rules": [
    {
      "name": "stock_cap",
      "measure": "stock",
      "scope": {
        "year": [1, 2, 3, 4, 5],
        "industry": ["coal", "steel", "transport"]
      },
      "sense": "<=",
      "value": 100
    }
  ],
  "note": "A cap is placed on the total stock held in each year and industry, limiting it to 100 million USD."
}

